#include <arpa/inet.h>
#include <fcntl.h>
#include <netinet/in.h>
#include <poll.h>
#include <sys/socket.h>
#include <unistd.h>
#include <array>
#include <iostream>
#include <string>
int main(){std::string payload;std::cin>>payload;const int receiver=socket(AF_INET,SOCK_DGRAM,0);sockaddr_in address{};address.sin_family=AF_INET;address.sin_addr.s_addr=htonl(INADDR_LOOPBACK);address.sin_port=0;bind(receiver,reinterpret_cast<sockaddr*>(&address),sizeof(address));socklen_t length=sizeof(address);getsockname(receiver,reinterpret_cast<sockaddr*>(&address),&length);fcntl(receiver,F_SETFL,O_NONBLOCK);const int sender=socket(AF_INET,SOCK_DGRAM,0);sendto(sender,payload.data(),payload.size(),0,reinterpret_cast<sockaddr*>(&address),sizeof(address));pollfd event{receiver,POLLIN,0};const int ready=poll(&event,1,1000);std::array<char,128> buffer{};const auto received=ready>0?recvfrom(receiver,buffer.data(),buffer.size(),0,nullptr,nullptr):-1;close(sender);close(receiver);if(received<0){std::cout<<"event=timeout\n";return 0;}std::cout<<"event=readable bytes="<<received<<" payload="<<std::string(buffer.data(),static_cast<std::size_t>(received))<<"\n";}

